union DGroupImage {
    uint8_t raw[DS_SIZE];
    struct DGroup g;
};
extern union DGroupImage dgroup;   /* initialised from DATA.OVL in data.c */
#define dg (dgroup.g)

/* Raw ds-offset access (the original code addresses tables and strings this way). */
static inline uint8_t *ds_ptr(uint16_t off) { return &dgroup.raw[off]; }
static inline const char *ds_str(uint16_t off) { return (const char *)&dgroup.raw[off]; }
static inline uint8_t ds_u8(uint16_t off) { return dgroup.raw[off]; }
static inline uint16_t ds_u16(uint16_t off) { return (uint16_t)(dgroup.raw[off] | dgroup.raw[off + 1] << 8); }
static inline void ds_set_u8(uint16_t off, uint8_t v) { dgroup.raw[off] = v; }
static inline void ds_set_u16(uint16_t off, uint16_t v) { dgroup.raw[off] = (uint8_t)v; dgroup.raw[off + 1] = (uint8_t)(v >> 8); }

/* For code that computes ds offsets which can stray outside the segment (the original then touches
 * other memory): a pointer into the segment, or to a scratch byte when off is outside it. */
extern uint8_t ds_outside;
static inline uint8_t *ds_at(long off) { return (off < 0 || off >= DS_SIZE) ? &ds_outside : &dgroup.raw[off]; }

/* Saved game: SAVED.GAM / INIT.GAM are the raw bytes ds[SAVE_OFFSET .. SAVE_OFFSET + SAVE_SIZE). */
int  dgroup_load_game(const char *path);    /* 0 on success */
int  dgroup_save_game(const char *path);
void dgroup_reset(void);                    /* back to the DATA.OVL initial image */

#endif
